examples.template:
MonarchPlanCard(
    {{name}},
    price: {{price}},
    period: {{period}},
    priceNote: {{priceNote}},
    description: {{description}},
    featuresLabel: {{featuresLabel}},
    features: [
        MonarchPlanCardFeature({{features.0.label}}),
        MonarchPlanCardFeature({{features.1.label}}, hint: {{features.1.hint}}),
        MonarchPlanCardFeature({{features.2.label}}, isIncluded: {{features.2.included}}),
    ],
    badge: {{badge}},
    isHighlighted: {{highlighted}}
) {
    MonarchButton(
        {{action.label}},
        variant: {{action.variant|case}},
        size: {{action.size|case}},
        fullWidth: true
    ) { choose() }
}
